import java.util.*;
import java.io.*;

public class Main {
    static int[] findSubset(int[] arr, int target) {
        // Return the chosen elements in array order, or an empty array if no subset exists.
        // Write your solution here
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int target = (int) in.nval;
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken(); arr[i] = (int) in.nval;
        }
        int[] res = findSubset(arr, target);
        if (res.length == 0) {
            System.out.println("No subset found");
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
